sealed class ApiResult<T> {
  const ApiResult();
  factory ApiResult.fromJson(Object? value, T Function(Object?) decode) {
    final data = _record(value);
    if (data.length == 2 && data['ok'] == true && data.containsKey('value'))
      return ApiSuccess<T>(decode(data['value']));
    if (data.length == 2 &&
        data['ok'] == false &&
        data['error'] is Map<String, Object?>) {
      final error = _record(data['error']);
      if (error.length == 1 && error['code'] is String) {
        for (final code in ApiErrorCode.values) {
          if (code.name == error['code']) return ApiFailure<T>(code);
        }
      }
    }
    throw const FormatException('Invalid API result');
  }
}

final class ApiSuccess<T> extends ApiResult<T> {
  const ApiSuccess(this.value);
  final T value;
}

final class ApiFailure<T> extends ApiResult<T> {
  const ApiFailure(this.code);
  final ApiErrorCode code;
}
